update
    posts_content
set content = #{po.content},
    content_type= #{po.contentType}
where id = #{po.id}

mapper.select:
select p.id as id, title, image, is_vip, td.create_time as create_time, td.status as status from
    (select target_id, create_time, status from likes

            type = #{type} and user_id = #{userId} and status = 0
             and date(create_time) >= #{beginTime}
             and date(create_time) <= #{endTime}
        ) td
        left join
    posts p
    on td.target_id = p.id where p.status = 2

SELECT p.id AS id, p.title AS title, p.introduction AS introduction, p.image AS image, p.type AS type, p.post_type AS post_type, p.create_time AS create_time, p.update_time AS update_time, IFNULL(browse_count.browse_count, 0) AS browse_count, IFNULL(like_count.like_count, 0) AS like_count, IFNULL(collect_count.collect_count, 0) AS collect_count FROM posts p LEFT JOIN ( SELECT post_id, COUNT(*) AS browse_count FROM browse WHERE type = 0 GROUP BY post_id ) browse_count ON p.id = browse_count.post_id LEFT JOIN ( SELECT target_id AS post_id, COUNT(*) AS like_count FROM likes WHERE type = 0 AND status = 0 GROUP BY target_id ) like_count ON p.id = like_count.post_id LEFT JOIN ( SELECT post_id, COUNT(*) AS collect_count FROM collect WHERE status = 0 GROUP BY post_id ) collect_count ON p.id = collect_count.post_id WHERE p.author_id = #{userId} AND p.status = 2 (AND p.type = 0 OR p.type = 2)
AND ( p.create_time < #{lastCreateTime} OR (p.create_time = #{lastCreateTime} AND p.id < #{lastId}) )
ORDER BY p.create_time DESC, p.id DESC LIMIT #{size}

SELECT p.id AS id, ui.user_id AS user_id, ui.user_name AS user_name, ui.image AS avatar, p.title AS title, p.introduction AS introduction, p.image AS image, p.type AS type, p.post_type AS post_type, p.create_time AS create_time, p.update_time AS update_time, IFNULL(browse_count.browse_count, 0) AS browse_count, IFNULL(like_count.like_count, 0) AS like_count, IFNULL(collect_count.collect_count, 0) AS collect_count, IFNULL(interest_score.total_weight, 0) AS interest_score FROM posts p LEFT JOIN ( SELECT post_id, COUNT(*) AS browse_count FROM browse WHERE type = 0 GROUP BY post_id ) browse_count ON p.id = browse_count.post_id LEFT JOIN ( SELECT target_id AS post_id, COUNT(*) AS like_count FROM likes WHERE type = 0 AND status = 0 GROUP BY target_id ) like_count ON p.id = like_count.post_id LEFT JOIN ( SELECT post_id, COUNT(*) AS collect_count FROM collect WHERE status = 0 GROUP BY post_id ) collect_count ON p.id = collect_count.post_id LEFT JOIN ( SELECT pt.post_id, SUM(ui.weight) AS total_weight FROM post_tag pt JOIN user_interest ui ON pt.tag_id = ui.tag_id WHERE ui.user_id = #{userId} GROUP BY pt.post_id ) interest_score ON p.id = interest_score.post_id LEFT JOIN user_info ui ON p.author_id = ui.user_id WHERE p.status = 2 and p.post_type = #{postType} and p.type = 0
AND ( (IFNULL(interest_score.total_weight, 0) < #{lastInterestScore}) OR (IFNULL(interest_score.total_weight, 0) = #{lastInterestScore} AND p.create_time < #{lastCreateTime}) OR (IFNULL(interest_score.total_weight, 0) = #{lastInterestScore} AND p.create_time = #{lastCreateTime} AND p.id < #{lastId}) )
ORDER BY interest_score DESC, p.create_time DESC, p.id DESC LIMIT #{size}

SELECT p.id AS id, ui.user_id AS user_id, ui.user_name AS user_name, ui.image AS avatar, p.title AS title, p.introduction AS introduction, p.image AS image, p.type AS type, p.post_type AS post_type, p.create_time AS create_time, p.update_time AS update_time, IFNULL(browse_count.browse_count, 0) AS browse_count, IFNULL(like_count.like_count, 0) AS like_count, IFNULL(collect_count.collect_count, 0) AS collect_count FROM posts p LEFT JOIN ( SELECT post_id, COUNT(*) AS browse_count FROM browse WHERE type = 0 GROUP BY post_id ) browse_count ON p.id = browse_count.post_id LEFT JOIN ( SELECT target_id AS post_id, COUNT(*) AS like_count FROM likes WHERE type = 0 AND status = 0 GROUP BY target_id ) like_count ON p.id = like_count.post_id LEFT JOIN ( SELECT post_id, COUNT(*) AS collect_count FROM collect WHERE status = 0 GROUP BY post_id ) collect_count ON p.id = collect_count.post_id LEFT JOIN user_info ui ON p.author_id = ui.user_id
INNER JOIN post_tag pt ON p.id = pt.post_id AND pt.tag_id = #{tagId}
WHERE p.status = 2 and p.post_type = #{postType} and p.type = 0
AND ( p.create_time < #{lastCreateTime} OR (p.create_time = #{lastCreateTime} AND p.id < #{lastId}) )
ORDER BY p.create_time DESC, p.id DESC LIMIT #{size}

select p.id as article_id, ui.user_id as user_id, ui.user_name as user_name, ui.image as avatar, p.title as title, p.introduction as intro, p.image as cover, p.create_time as create_time, p.post_type as post_type from posts p left join user_info ui on p.author_id = ui.user_id inner join user_focus uf on p.author_id = uf.focus_user_id where p.status = 2 and uf.user_id = #{userId} and (p.type = 0 or p.type = 2)
and ( p.create_time < #{lastCreateTime} or (p.create_time = #{lastCreateTime} and p.id < #{lastTargetId}) )
order by p.create_time desc, p.id desc limit #{size}
